/// Lesson sections for the info page — never shown on the practice screen.
const List<TechniqueSection> grooveHihatOpenLesson = [
  TechniqueSection(
    title: "Why it matters",
    body:
        "The hi-hat is two instruments in one: closed it ticks, open it washes. Opening it on the right note and closing it exactly on the next makes a plain beat breathe — the difference between a drum machine and a drummer.",
  ),
  TechniqueSection(
    title: "How to play it",
    body:
        "Lift the left foot just before the open note so the cymbals ring loosely, then press it down again on the next count so the \"chick\" lands in time. The open note gets the stick, the close gets the foot; both matter as much as the snare.",
  ),
  TechniqueSection(
    title: "Practice tips",
    body:
        "Line 1 opens only on the \"and\" of 4, line 2 on both \"ands\" of 2 and 4, line 3 is the disco beat with every \"and\" open over four-on-the-floor. Lines 4 and 5 practise the foot alone: a pedal \"chick\" on 1, then the foot keeping quarters under a ride.",
  ),
  TechniqueSection(
    title: "Where you hear it",
    body:
        "Disco on every offbeat (Chic \"Le Freak\", Gloria Gaynor \"I Will Survive\"), the hi-hat barks in AC/DC's rock grooves, and Stewart Copeland's splashy hats in the Police.",
  ),
];
